select table_name from information_schema.tables where table_schema='public' and table_name in ('companies','company_members','branches','cost_centers','fiscal_periods','accounts','journal_entries','journal_lines','parties','units','products','warehouses','inventory_movements','cash_drawers','payment_methods','pos_shifts','sales_invoices','sales_invoice_lines','sales_payments','audit_log') order by table_name;